BEGIN;
SELECT plan(16);
INSERT INTO public.staff(id,first_name,last_name,role,status) VALUES('fa251000-0000-4000-8000-000000000001','Schedule','Admin','ADMINSTAFF','ACTIVE');
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT public.email_apply_sync_page('drafts',NULL,'s1',true,'[{"id":"schedule-contract","threadId":"schedule-contract-thread","draft":true,"changeKey":"one","bodyText":"Scheduled text"}]','{}');
SELECT is(public.email_schedule_send('schedule-contract','one','fa251000-0000-4000-8000-000000000001','fa251000-0000-4000-8000-000000000010',now()+interval '1 hour')->>'state','scheduled','schedule reserves a versioned draft durably');
SELECT is(public.email_schedule_send('schedule-contract','one','fa251000-0000-4000-8000-000000000001','fa251000-0000-4000-8000-000000000010',now()+interval '1 hour')->>'state','scheduled','retrying the same schedule does not duplicate it');
SELECT is((SELECT count(*) FROM public.email_claim_scheduled_sends()),0::bigint,'future mail is not claimed early');
SELECT is(public.email_begin_send('schedule-contract','one','fa251000-0000-4000-8000-000000000001','fa251000-0000-4000-8000-000000000011')->>'proceed','false','manual send cannot race a scheduled reservation');
SELECT is(public.email_claim_draft('schedule-contract','one','fa251000-0000-4000-8000-000000000001','fa251000-0000-4000-8000-000000000012')->>'state','submitted','portal edits cannot change a scheduled version');
SELECT is(public.email_cancel_schedule('fa251000-0000-4000-8000-000000000010')->>'state','cancelled','cancel before dispatch releases the draft');
SELECT throws_ok($$SELECT public.email_schedule_send('schedule-contract','one','fa251000-0000-4000-8000-000000000001','fa251000-0000-4000-8000-000000000013',now()-interval '1 minute')$$,'P0001','Choose a future send time within one year','past scheduling is rejected');
SELECT public.email_schedule_send('schedule-contract','one','fa251000-0000-4000-8000-000000000001','fa251000-0000-4000-8000-000000000014',now()+interval '1 hour');
UPDATE public.email_send_attempts SET scheduled_at=now()-interval '1 minute' WHERE message_id='schedule-contract';
SELECT is((SELECT count(*) FROM public.email_claim_scheduled_sends()),1::bigint,'due mail has one durable dispatch claim');
SELECT is((SELECT count(*) FROM public.email_claim_scheduled_sends()),0::bigint,'a second worker cannot submit a claimed delivery');
SELECT is(public.email_cancel_schedule('fa251000-0000-4000-8000-000000000014')->>'state','busy','a dispatch already in progress cannot be cancelled');
SELECT is(public.email_begin_send('schedule-contract','one','fa251000-0000-4000-8000-000000000001','fa251000-0000-4000-8000-000000000015')->>'proceed','false','a worker crash cannot cause manual duplicate sending');
SELECT public.email_apply_sync_page('drafts','','',false,'[{"id":"queue-one","threadId":"queue-one-thread","draft":true,"changeKey":"one"},{"id":"queue-two","threadId":"queue-two-thread","draft":true,"changeKey":"one"}]','{}',true);
SELECT public.email_schedule_send('queue-one','one','fa251000-0000-4000-8000-000000000001','fa251000-0000-4000-8000-000000000021',now()+interval '1 hour');
SELECT public.email_schedule_send('queue-two','one','fa251000-0000-4000-8000-000000000001','fa251000-0000-4000-8000-000000000022',now()+interval '1 hour');
UPDATE public.email_send_attempts SET scheduled_at=now()-interval '1 minute' WHERE message_id IN ('queue-one','queue-two');
SELECT is((SELECT count(*) FROM public.email_claim_scheduled_sends()),1::bigint,'a bounded request reserves only the job it is about to process');
SELECT is((SELECT count(*) FROM public.email_send_attempts WHERE state='scheduled'),1::bigint,'a slow/crashed worker leaves unstarted mail available for the next tick');
SELECT is((SELECT count(*) FROM public.email_claim_scheduled_sends()),1::bigint,'another tick can independently process the remaining due mail');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT * FROM public.email_claim_scheduled_sends()$$,'42501','permission denied for function email_claim_scheduled_sends','browser cannot claim a worker batch');
SELECT throws_ok($$SELECT public.email_schedule_send('schedule-contract','one','fa251000-0000-4000-8000-000000000001','fa251000-0000-4000-8000-000000000016',now()+interval '1 hour')$$,'42501','permission denied for function email_schedule_send','browser cannot bypass the authorized command interface');
SELECT * FROM finish();
ROLLBACK;
